window.QUIZ = (window.QUIZ || []).concat([
  { id: "5-001", ch: 5, sec: "5.2", page: 79, type: "recall", level: 1,
    q: "What are the three general types of irrigation systems named in Chapter 5?",
    opts: ["Gravity, pressurized, and subsurface","Center pivot, furrow, and drip","Sprinkler, surface, and microirrigation","Basin, border, and furrow"], a: 2,
    why: "The book groups all systems into sprinkler, surface, and microirrigation (drip, trickle, and spray). Basin, border, and furrow are kinds of surface irrigation, and center pivot is one kind of sprinkler system.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-002", ch: 5, sec: "5.2.1", page: 79, type: "recall", level: 1,
    q: "Sprinkler systems are divided into four basic types. Which list matches the book?",
    opts: ["Single-sprinkler, solid-set, moved lateral, and moving lateral","Hand move, side roll, center pivot, and linear move","Impact, spray, rotator, and gun","Low, medium, high, and very high pressure"], a: 0,
    why: "The four basic types are single-sprinkler, solid-set, moved lateral, and moving lateral. Hand move and side roll are examples of moved laterals, and center pivot and linear move are moving laterals.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-003", ch: 5, sec: "5.2.1", page: 79, type: "recall", level: 1,
    q: "A lateral-based sprinkler system whose laterals stay permanently in one place in the field is called a",
    opts: ["solid-set system","moved lateral system","traveler system","side roll system"], a: 0,
    why: "When the laterals are placed permanently in one location the system is solid-set, common on lawns, golf courses and some horticultural crops. Side roll and hand move laterals are moved between sets, and a traveler is a single big gun sprinkler.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-004", ch: 5, sec: "5.1", page: 79, type: "recall", level: 1,
    q: "Chapter 5 says irrigation management should be based on desired outcomes. Which list matches the example goals it gives?",
    opts: ["Only maximizing yield regardless of cost","Maximizing water applied, minimizing labor, and maximizing pressure","Maximizing profit, producing a contracted yield, optimizing water use, produce quality, or an attractive landscape","Only minimizing energy use"], a: 2,
    why: "The introduction lists goals from maximizing profit to producing a contracted yield, optimizing water resource use, maintaining produce quality, or assuring an attractive landscape, all within economic, energy, environmental, labor and water constraints.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-005", ch: 5, sec: "5.3.1", page: 82, type: "recall", level: 1,
    q: "For sprinklers, how large are evaporation losses usually, as a share of the applied water?",
    opts: ["About 25 to 30%","About 15 to 20%","Significantly less than 10%","More than 30% on most days"], a: 2,
    why: "The book states that research shows little evaporation of drops in the air and that evaporation losses are usually significantly less than 10% of applied water. Drift is often larger than evaporation.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-006", ch: 5, sec: "5.3.1", page: 82, type: "recall", level: 1,
    q: "Sprinkler water that wind carries outside the land being irrigated is called",
    opts: ["drift","runoff","droplet evaporation","deep percolation"], a: 0,
    why: "Drift is water blown outside the target area. It is often significantly higher than evaporation loss. Runoff moves over the soil surface and deep percolation moves below the root zone.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-007", ch: 5, sec: "5.3.1", page: 83, type: "recall", level: 1,
    q: "Application efficiency (Ea) is defined as",
    opts: ["the low-quarter depth divided by the mean depth infiltrated","the fraction of the field that receives the desired depth or more","the fraction of applied water that is stored in the root zone and available for the crop","the water delivered to the field divided by the water diverted at the source"], a: 2,
    why: "Ea = dn / da × 100%, net irrigation stored in the root zone over gross depth applied. The other choices define adequacy, DU and conveyance efficiency.",
    eq: "5.1", calc: "eq-5.1", fig: null, table: null },
  { id: "5-008", ch: 5, sec: "5.3.2", page: 83, type: "recall", level: 1,
    q: "In the distribution uniformity equation, what is dLQ?",
    opts: ["The single smallest depth caught in the test","The average of the lowest one-quarter of measured depths, each representing an equal area","The depth that 25% of the field receives or more","The mean depth minus 25%"], a: 1,
    why: "Rank the observed depths and average the smallest 25% of them. That average is dLQ, and DU = dLQ / dz. It is an average, not the single lowest can.",
    eq: "5.2", calc: "eq-5.2", fig: null, table: null },
  { id: "5-009", ch: 5, sec: "5.3.2", page: 86, type: "recall", level: 1,
    q: "For moved lateral sprinkler systems, what is commonly the lowest acceptable uniformity?",
    opts: ["CU of 60 (DU of 0.5)","CU of 90 (DU of 0.85)","CU of 70 (DU of 0.6)","CU of 80 (DU of 0.7)"], a: 3,
    why: "The book gives CU 80 or DU 0.7 as the lowest acceptable value for moved laterals. Pivots often reach CUH 90, and DU 0.6 is the floor quoted for furrows.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-010", ch: 5, sec: "5.3.2", page: 86, type: "recall", level: 1,
    q: "What DU is frequently quoted as the lowest acceptable value for furrow irrigation?",
    opts: ["0.9","0.8","0.7","0.6"], a: 3,
    why: "For furrow systems a DU of 0.6 is frequently the lowest acceptable value. 0.7 is the moved lateral sprinkler guideline and 0.8 is the minimum for microirrigation emission uniformity.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-011", ch: 5, sec: "5.3.2", page: 86, type: "recall", level: 2,
    q: "The DU of a microirrigation system, also called emission uniformity, should be at least",
    opts: ["0.6","0.8","0.7","0.95"], a: 1,
    why: "The book says emission uniformity for microirrigation should be at least 0.8. Lower values are accepted for furrows (0.6) and moved laterals (0.7).",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-012", ch: 5, sec: "5.3.2", page: 86, type: "recall", level: 1,
    q: "What Heermann and Hein uniformity (CUH) is often achieved by center pivots?",
    opts: ["90","80","70","99"], a: 0,
    why: "For center pivots a CUH of 90 is often achieved. A CU of 80 is the lower limit for moved lateral systems, not a pivot target.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-013", ch: 5, sec: "5.3.2", page: 85, type: "recall", level: 1,
    q: "For a center pivot uniformity test, catch containers are placed along two radial lines at what spacing?",
    opts: ["Uniform spacing of 5 to 15 ft","Uniform spacing of 1 to 2 ft","One can at each tower","Uniform spacing of 50 to 100 ft"], a: 0,
    why: "Cans are usually placed 5 to 15 ft apart along each of two radial lines, and the pivot passes over them. One can per tower would miss the variation between nozzles.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-014", ch: 5, sec: "5.3.3", page: 86, type: "recall", level: 1,
    q: "Adequacy of irrigation is",
    opts: ["the percent of time the system can operate","the percent of applied water stored in the root zone","the ratio of the low-quarter depth to the mean depth","the percent of the field that receives the desired depth of water or more"], a: 3,
    why: "Adequacy is the share of the area that gets at least the desired depth. It is read from a frequency distribution of infiltrated depth like Figure 5.6. The other choices are Ea, DU and the complement of downtime.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-015", ch: 5, sec: "5.3.3", page: 86, type: "recall", level: 2,
    q: "Well designed and managed irrigation systems should adequately irrigate at least what share of the field?",
    opts: ["98 to 100%","50 to 60%","65 to 75%","80 to 90%"], a: 3,
    why: "The book says well designed and managed systems should adequately irrigate at least 80 to 90% of the field. Aiming for 100% would require large deep percolation losses with any real nonuniformity.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-016", ch: 5, sec: "5.3.4", page: 87, type: "recall", level: 2,
    q: "Managing irrigation to the average low-quarter depth results in approximately",
    opts: ["100% adequately irrigated with no deficit","75% adequately irrigated and 25% under irrigated","50% adequately irrigated and 50% under irrigated","90% of the field adequately irrigated and about 10% under irrigated"], a: 3,
    why: "Using dLQ as the management depth gives about 90% adequacy, with about 10% of the field under irrigated. It is not 75/25 even though dLQ is built from the lowest quarter of the cans.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-017", ch: 5, sec: "5.3.4", page: 87, type: "recall", level: 2,
    q: "What is the effective depth (de) of an irrigation?",
    opts: ["The gross depth applied minus evaporation and drift","Irrigation water that remains in the root zone for plant use, accounting for SWD and assuming depth above dLQ is lost","The mean depth infiltrated over the whole field","The depth applied from the original water source"], a: 1,
    why: "de is the managed term used in scheduling. It equals dLQ when dLQ is less than SWD, and SWD when dLQ is greater (Eq. 5.9 and 5.10). The gross minus evaporation and drift is closer to dz plus runoff.",
    eq: "5.9", calc: "eq-5.9-5.11", fig: null, table: null },
  { id: "5-018", ch: 5, sec: "5.3.5", page: 90, type: "recall", level: 1,
    q: "The scheduling coefficient (SC) is the inverse of which index?",
    opts: ["Christiansen uniformity (CU)","Distribution uniformity (DU)","Application efficiency (Ea)","Conveyance efficiency (Ec)"], a: 1,
    why: "SC = dz / dLQ, which is 1 / DU. It is commonly used for turf sprinkler systems to stretch run times for nonuniformity.",
    eq: "5.13", calc: "eq-5.13", fig: null, table: null },
  { id: "5-019", ch: 5, sec: "5.3.6", page: 91, type: "recall", level: 1,
    q: "In Cl = 0.226 C dp, what units go with each term?",
    opts: ["Cl in kg/ha, C in mg/L, dp in mm","Cl in lb/ac, C in ppm, dp in inches","Cl in lb/ac, C in ppm, dp in feet","Cl in lb, C in percent, dp in ac-in"], a: 1,
    why: "The 0.226 constant converts ppm times inches of water to pounds per acre (1 ac-in of water weighs about 226,000 lb). Using feet or metric units with 0.226 gives wrong answers.",
    eq: "5.18", calc: "eq-5.18", fig: null, table: null },
  { id: "5-020", ch: 5, sec: "5.3.7", page: 92, type: "recall", level: 1,
    q: "Conveyance efficiency (Ec) is defined as",
    opts: ["low-quarter depth divided by water applied","water stored in the root zone divided by water applied","water delivered to the irrigated area and applied divided by water diverted from the source","water consumed by ET divided by water diverted"], a: 2,
    why: "Ec = da / ds × 100%. It describes the delivery system, not the field application. Root zone storage over applied water is application efficiency.",
    eq: "5.19", calc: "eq-5.19", fig: null, table: null },
  { id: "5-021", ch: 5, sec: "5.3.7", page: 92, type: "recall", level: 2,
    q: "Doorenbos and Pruitt define distribution efficiency (Ed) as",
    opts: ["Ea × Eb","Ec × Eb","Ec × Ea","Ec × Eb × Ea"], a: 1,
    why: "Distribution efficiency combines supply conveyance efficiency and field canal efficiency, Ed = Ec × Eb. Farm efficiency is Ea × Eb.",
    eq: null, calc: "project-efficiency", fig: null, table: null },
  { id: "5-022", ch: 5, sec: "5.3.7", page: 92, type: "recall", level: 2,
    q: "Doorenbos and Pruitt define farm efficiency (Ef) as",
    opts: ["Ec × Eb","Ea × Eb","Ec × Ea","Ea ÷ Ec"], a: 1,
    why: "Farm efficiency combines the field canal efficiency and the field application efficiency, Ef = Ea × Eb. Ec × Eb is distribution efficiency.",
    eq: null, calc: "project-efficiency", fig: null, table: null },
  { id: "5-023", ch: 5, sec: "5.3.7", page: 92, type: "recall", level: 2,
    q: "The USDA-SCS guide suggests what loss for ditch side vegetation?",
    opts: ["0.5 to 1.0% of the flow per 1,000 ft","5 to 10% of the flow per mile","0.5 to 1.0% of the flow per mile","0.01 to 0.15 ft³/ft²/d"], a: 2,
    why: "Ditch side vegetation loses about 0.5 to 1.0% per mile. The 0.01 to 0.15 ft³/ft²/d range is the guide value for buried pipelines.",
    eq: null, calc: "ditch-seepage", fig: null, table: null },
  { id: "5-024", ch: 5, sec: "5.3.7", page: 92, type: "recall", level: 2,
    q: "What seepage range does the USDA-SCS guide give for a buried pipeline, depending on age and pipe type?",
    opts: ["0.2 to 0.3 ft³/ft²/d","0.01 to 0.15 ft³/ft²/d","1.15 to 1.65 ft³/ft²/d","0.5 to 1.0% per mile"], a: 1,
    why: "Buried pipelines lose 0.01 to 0.15 ft³/ft²/d. 0.2 to 0.3 is the concrete ditch band in Figure 5.8 and 1.15 to 1.65 is loam and sandy loam.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-025", ch: 5, sec: "5.4", page: 94, type: "recall", level: 2,
    q: "Which standard is cited for uniformity testing of mechanized irrigation systems such as center pivots?",
    opts: ["ASCE-EWRI standardized reference ET","ANSI/ASAE S397.4","ANSI/ASAE S362.2","ANSI/ASAE S436.2"], a: 3,
    why: "S436.2 (2020) is the test procedure for mechanized systems. S397.4 and S362.2 are cited in Section 5.9 for electrical safety.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-026", ch: 5, sec: "5.5", page: 95, type: "recall", level: 1,
    q: "What conversion does the book give between depth per day and flow per unit area?",
    opts: ["1 in/d = 1.0 gpm/ac","1 in/d = 452 gpm/ac","1 in/d = 27.15 gpm/ac","1 in/d = 18.86 gpm/ac"], a: 3,
    why: "1 in/d over 1 ac is 27,154 gal per 1,440 min, which is 18.86 gpm/ac. The 452 (about 450) figure is the gpm in 1 ac-in/hr, and 27,154 is gallons per ac-in.",
    eq: "5.20", calc: "eq-5.20", fig: null, table: null },
  { id: "5-027", ch: 5, sec: "5.6", page: 95, type: "recall", level: 2,
    q: "With the peak ET design method, the net capacity is normally chosen to meet the peak daily ET how often?",
    opts: ["70% of the time (7 of 10 yr)","50% of the time (5 of 10 yr)","90% of the time (9 of 10 yr)","Every year without exception"], a: 0,
    why: "Annual maximum daily ET values are ranked, and the capacity that meets peak daily ET in 7 of 10 yr is normally taken as acceptable.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-028", ch: 5, sec: "5.7", page: 99, type: "recall", level: 1,
    q: "In irrigation operations, a set (or station) is",
    opts: ["the time the system is idle in a cycle","the time between starting successive irrigations","the smallest subdivision of the area that can be irrigated separately, the area watered at one time","the total area under one water right"], a: 2,
    why: "A set is the area irrigated at one time, such as the land under a stationary moved lateral or a block of furrows. Landscape systems call it a station after the controller stations.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-029", ch: 5, sec: "5.7", page: 99, type: "recall", level: 2,
    q: "What is the difference between application time and set time?",
    opts: ["They always mean the same thing","Application time is the time between irrigations, set time is how long water is applied","Application time is how long water is applied to a set, set time is the time between starting successive sets","Application time includes moving the lateral, set time does not"], a: 2,
    why: "Set time runs from the start of one set to the start of the next. If laterals must drain or be moved, set time is longer than application time. The time between irrigations is the cycle time.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-030", ch: 5, sec: "5.9", page: 101, type: "recall", level: 1,
    q: "Many irrigation pumps and pivot drive motors run on what high voltage supply, making electrical safety a major concern?",
    opts: ["120 V","480 V","240 V","12 V"], a: 1,
    why: "The book notes many systems use a 480 V supply. Metal structures in a wet environment create an electrocution risk, so wiring must follow the codes and standards cited.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-031", ch: 5, sec: "5.10", page: 102, type: "recall", level: 2,
    q: "Which three terms do Perry et al. (2009) suggest when hydrological conservation is the concern?",
    opts: ["Transpiration, evaporation, and drift fraction","Application, conveyance, and distribution efficiency","Net, gross, and farm capacity","Consumed fraction, recoverable fraction, and non-recoverable fraction"], a: 3,
    why: "Because irrigation efficiency does not say where unused water goes, Perry et al. suggest consumed, recoverable and non-recoverable fractions. The other lists are performance or capacity terms.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-032", ch: 5, sec: "5.10", page: 102, type: "recall", level: 2,
    q: "At the watershed scale, consumptive use is defined as",
    opts: ["water diverted for use that is not returned to the water resource system","all water pumped or diverted for irrigation","water that percolates below the root zone","water that runs off the field to a stream"], a: 0,
    why: "Consumptive use is diverted water that does not return, mainly ET in farm watersheds. Deep percolation and runoff often return to aquifers or streams, and cooling water from a power plant is not consumptive.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-033", ch: 5, sec: "5.2.1", page: 79, type: "concept", level: 2,
    q: "What is the main disadvantage of single-sprinkler systems such as a big gun traveler?",
    opts: ["They generally apply water beyond the irrigated area to make sure the target land is watered","They cannot be used on irregularly shaped fields","They require no pressure and so cannot be automated","They can only apply very small depths"], a: 0,
    why: "The book says single-sprinkler systems usually throw water past the target area to cover it. Their big advantage is versatility on irregularly shaped land, so the second choice is backwards.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-034", ch: 5, sec: "5.2.1", page: 80, type: "concept", level: 2,
    q: "Why do moved lateral systems (hand move, tow line, side roll) usually apply large depths each irrigation?",
    opts: ["Their nozzles are larger than pivot nozzles","They operate at very high pressure","Moving them takes labor, so they are left in place 8 to 24 hr","They are only used on soils with high intake rates"], a: 2,
    why: "Labor to move the lateral sets the schedule. Long sets of 8, 12 or 24 hr mean large depths per irrigation, unlike a pivot whose speed controls depth.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-035", ch: 5, sec: "5.2.2", page: 80, type: "concept", level: 1,
    q: "Why is surface irrigation usually less expensive to operate per unit of water applied than sprinkler irrigation?",
    opts: ["It has lower pressure requirements","It needs less labor","It has higher application efficiency","It never produces runoff"], a: 0,
    why: "Surface systems need little or no pressure, so pumping cost is lower. They are actually labor intensive and often produce runoff, and their efficiency is usually lower than sprinklers.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-036", ch: 5, sec: "5.2.2", page: 80, type: "concept", level: 2,
    q: "Which set lists the three common problems of surface irrigation named in the book?",
    opts: ["High pressure, nozzle plugging, and wind drift","Runoff needed for fast advance, high labor, and deep percolation from nonuniform infiltration","Emitter clogging, filtration cost, and rodent damage","Tower rutting, end gun overlap, and drift"], a: 1,
    why: "Water must advance quickly so some runs off, the systems are labor intensive, and nonuniform infiltration causes deep percolation. Plugging and filtration are microirrigation issues and drift is a sprinkler issue.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-037", ch: 5, sec: "5.2.3", page: 82, type: "concept", level: 2,
    q: "Why is surface drip generally not used for row crops, and how is that overcome?",
    opts: ["Low efficiency on row crops, overcome by using microsprinklers","Expense and the need to remove it each season, overcome by burying laterals below the tillage zone (SDI)","Emitters cannot deliver enough water, overcome by doubling laterals","It causes runoff on slopes, overcome by terracing"], a: 1,
    why: "Cost and seasonal removal limit drip on row crops. Subsurface drip irrigation buries laterals beneath tillage so they stay in place. Drip is efficient and makes negligible runoff even on steep slopes.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-038", ch: 5, sec: "5.2.3", page: 82, type: "concept", level: 1,
    q: "Which pair of reasons explains the high efficiency of microirrigation?",
    opts: ["Large depths per irrigation and few irrigations","High pressure and large droplets that resist drift","Small evaporation because the whole area is not wetted, and very low rates so runoff is negligible","Water spread over the whole surface so roots grow evenly"], a: 2,
    why: "Microirrigation wets only part of the area and applies water slowly, so evaporation and runoff are small. It is also easy to automate.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-039", ch: 5, sec: "5.3.2", page: 83, type: "concept", level: 2,
    q: "Why is DU always between 0 and 1?",
    opts: ["It is the low-quarter average divided by the overall mean, and the mean is always at least as large","It is a probability that must be less than 1","It is divided by 100 by definition","Catch cans never collect more than the applied depth"], a: 0,
    why: "The average of the lowest quarter can never exceed the mean of all the data, so dLQ / dz is 1 or less. A larger DU means better uniformity.",
    eq: "5.2", calc: "eq-5.2", fig: null, table: null },
  { id: "5-040", ch: 5, sec: "5.3.2", page: 84, type: "concept", level: 3,
    q: "Catch-can depths are used in the CU equation. When do those depths represent the infiltrated water?",
    opts: ["Only if the wind is calm","Only if no surface runoff occurs","Only if the cans are spaced on a square grid","Only if evaporation from the cans is zero"], a: 1,
    why: "The CU equation was built for catch cans, but what matters is infiltration. Can depth equals infiltration only if water infiltrates where it lands, meaning no surface runoff or redistribution.",
    eq: "5.3", calc: "eq-5.3", fig: null, table: null },
  { id: "5-041", ch: 5, sec: "5.3.2", page: 85, type: "concept", level: 2,
    q: "Why is the Heermann and Hein coefficient weighted by distance from the pivot point?",
    opts: ["Nozzles are smaller near the pivot point","The pivot travels faster near the pivot point","The end gun adds water only on the outer span","A container far from the pivot point represents more area than one close to it"], a: 3,
    why: "Each can in a radial line represents a ring of area that grows with distance, so depths are weighted by Si. The weighted mean dz* uses the same weights (Eq. 5.5).",
    eq: "5.4", calc: "eq-5.4-5.5", fig: null, table: null },
  { id: "5-042", ch: 5, sec: "5.3.2", page: 86, type: "concept", level: 2,
    q: "The optimal value of CU or DU for a system depends on",
    opts: ["The price of water, crop value, drainage or water quality costs, and the cost of renovation or management changes","Only the soil texture","Only the crop root depth","Only the system pressure"], a: 0,
    why: "Uniformity is an index, not an efficiency. The book says the best value is an economic choice weighing water price, crop value, environmental costs and the cost of improving the system.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-043", ch: 5, sec: "5.3.3", page: 86, type: "concept", level: 3,
    q: "If the mean infiltrated depth equals the average SWD, what happens in a field with ordinary nonuniformity?",
    opts: ["About half the field gets more than needed and percolates, the other half is short and may be stressed","The whole field is refilled exactly with no losses","About 90% of the field is adequately irrigated","Only runoff losses occur"], a: 0,
    why: "With a symmetric spread around the mean, about half the area gets more than the SWD and half gets less. This is the tradeoff between deep percolation and stress that adequacy describes.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-044", ch: 5, sec: "5.3.3", page: 86, type: "concept", level: 3,
    q: "With an existing sprinkler system, a manager increases the average depth applied. What happens to the infiltration distribution curve?",
    opts: ["It shifts but adequacy cannot change","Its shape flattens, so uniformity improves","It stays the same because uniformity is fixed","It shifts proportionally and keeps its shape, so adequacy rises along with deep percolation"], a: 3,
    why: "Changing the average depth scales the curve without changing its shape. Adequacy goes up, but more of the field gets more than SWD, so deep percolation increases. Changing the shape for sprinklers needs system modification.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-045", ch: 5, sec: "5.3.4", page: 87, type: "concept", level: 3,
    q: "For sprinkler and microirrigation, nonuniformity of application is usually a result of ___, while excessive application is a result of ___.",
    opts: ["the soil, the weather","system management, a problem with the system","a problem with the system, system management","the weather, the crop"], a: 2,
    why: "The book separates the two deep percolation causes. Nonuniformity comes from the hardware for sprinklers and micro, while over application comes from management such as irrigating too often or too long.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-046", ch: 5, sec: "5.3.4", page: 87, type: "concept", level: 2,
    q: "The mean infiltrated depth dz from Eq. 5.7 (dz = dg − dr − dev) includes which water?",
    opts: ["Only water stored in the root zone","Water stored in the root zone plus deep percolation","Only water lost to deep percolation","Water stored in the root zone plus runoff"], a: 1,
    why: "Eq. 5.7 removes above-ground losses only. What infiltrates is split later into storage and deep percolation using dLQ and SWD.",
    eq: "5.7", calc: "eq-5.6-5.7", fig: null, table: null },
  { id: "5-047", ch: 5, sec: "5.3.4", page: 88, type: "concept", level: 3,
    q: "Deep percolation is caused by uniform but excessive application (as in Figure 5.7b). What management change fixes it?",
    opts: ["Lengthen the interval or shorten the run so infiltration does not exceed SWD, keeping SWD below AD","Replace the sprinkler nozzles","Increase the system pressure","Add a runoff recovery pit"], a: 0,
    why: "Excess application comes from irrigating too often or too long. The interval can be increased as long as SWD does not exceed AD. New nozzles fix nonuniformity, not over application.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-048", ch: 5, sec: "5.3.4", page: 88, type: "concept", level: 3,
    q: "Without runoff recovery, how do da and dg relate in the ELQ calculation?",
    opts: ["da equals dz","da is always larger than dg","da equals dg minus runoff","They are equal, the volume taken from the source divided by the area irrigated"], a: 3,
    why: "Without reuse, all water applied came from the original source, so da = dg. Only with a reuse system does da differ, through Eq. 5.12a or 5.12b.",
    eq: "5.11", calc: "eq-5.9-5.11", fig: null, table: null },
  { id: "5-049", ch: 5, sec: "5.3.4", page: 89, type: "concept", level: 2,
    q: "What is the difference between a closed and an open runoff recovery system?",
    opts: ["Closed uses a pipeline, open uses a ditch","Closed reapplies runoff on the same field, open reapplies it on a different field","Closed pumps to the well, open releases to a stream","Closed captures rain, open captures irrigation water"], a: 1,
    why: "For a closed system da = dg(1 − Rr Rt), because reused water returns to the same field. For an open system da = dg / (1 + Rr Rt).",
    eq: "5.12a", calc: "eq-5.12", fig: null, table: null },
  { id: "5-050", ch: 5, sec: "5.3.6", page: 90, type: "concept", level: 2,
    q: "In the chemical leaching procedure, deep percolation is split into which two parts?",
    opts: ["Vdp1 from nonuniformity and Vdp2 from excessive application","Vdp1 from runoff and Vdp2 from drift","Vdp1 from rain and Vdp2 from irrigation","Vdp1 from the top layer and Vdp2 from the bottom layer"], a: 0,
    why: "Vdp1 = Vz(1 − F1) is caused by nonuniformity at 90% adequacy, and Vdp2 ≈ 0.95 A(dLQ − SWD) is caused by over application. Their sum gives Vdp (Eq. 5.16).",
    eq: "5.16", calc: "eq-5.16-5.17", fig: null, table: null },
  { id: "5-051", ch: 5, sec: "5.3.6", page: 90, type: "concept", level: 3,
    q: "Eq. 5.14 for deep percolation from nonuniformity assumes which conditions?",
    opts: ["100% adequacy and uniform depths","90% adequacy and normally distributed application depths","50% adequacy and any distribution","No deep percolation from excessive application"], a: 1,
    why: "Vdp1 = Vz(1 − F1) with F1 from Table 5.1 is stated for 90% adequacy and a statistically normal distribution of depths. Excess application is handled separately by Eq. 5.15.",
    eq: "5.14", calc: "eq-5.14", fig: null, table: null },
  { id: "5-052", ch: 5, sec: "5.3.7", page: 92, type: "concept", level: 2,
    q: "Which list gives the ways water is lost in conveyance named in the book?",
    opts: ["Deep percolation below roots and capillary rise","Drift, droplet evaporation, and runoff","Seepage, evaporation from water surfaces, ET of phreatophytes, and operational spills","Leaching, volatilization, and denitrification"], a: 2,
    why: "Canals lose water to seepage, open water evaporation, ET by phreatophytes along the ditch, and operational losses such as spills. Drift and runoff are field application losses.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-053", ch: 5, sec: "5.3.7", page: 92, type: "concept", level: 2,
    q: "Why can operational problems in a delivery system lower conveyance efficiency even with no seepage?",
    opts: ["Canal water warms and evaporates faster when ordered","Pumps lose efficiency at low flow","Water ordered but not taken may spill, and very small orders may need extra flow to deliver","Measurement flumes always over read"], a: 2,
    why: "If an irrigator orders water then declines the full supply, it may spill. If only a few irrigators order, the canal may need excess flow to deliver small amounts. Both reduce Ec.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-054", ch: 5, sec: "5.4", page: 95, type: "concept", level: 2,
    q: "Which activities belong to occasional rather than frequent system evaluation?",
    opts: ["Measuring application uniformity (CU or DU) and checking pumping plant performance","Checking flow rate and pressure","Looking for leaks and runoff","Checking that pressure matches design pressure"], a: 0,
    why: "The book lists uniformity tests and pump efficiency checks as occasional. Flow, pressure, leaks and runoff are frequent checks, now easier with cloud monitoring.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-055", ch: 5, sec: "5.5", page: 95, type: "concept", level: 2,
    q: "How do net and gross system capacity differ?",
    opts: ["Net includes conveyance losses, gross does not","Net is the supply rate needed to keep soil water above a set level, gross adds system inefficiency and downtime","Net is in gpm and gross is in in/d","Gross is for one field and net is for the farm"], a: 1,
    why: "Cg = Cn / [(ELQ/100)(1 − Dt/100)]. Both can be in in/d or gpm/ac. On-farm conveyance losses are added later through Eq. 5.21.",
    eq: "5.20", calc: "eq-5.20", fig: null, table: null },
  { id: "5-056", ch: 5, sec: "5.6", page: 96, type: "concept", level: 3,
    q: "In which two ways can soil water reduce the required system capacity?",
    opts: ["It raises the ET rate and lowers rainfall","It covers short periods when ET exceeds capacity and is refilled in surplus periods, and it allows depletion down to AD","It increases application efficiency and reduces downtime","It reduces runoff and drift"], a: 1,
    why: "Soil water buffers short shortages that are refilled during surplus periods (Figure 5.9), and depletion down to AD can be used during critical periods (Figure 5.10).",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-057", ch: 5, sec: "5.6", page: 98, type: "concept", level: 2,
    q: "Capacities determined with soil water or crop simulation models are usually very dependent on which property?",
    opts: ["The sprinkler pressure","The pump efficiency","The conveyance efficiency","The available water capacity (AWC) of the soil"], a: 3,
    why: "A larger AWC and root zone give a larger AD, which lets stored water cover peak periods and lowers the required capacity, as Figure 5.11 shows.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-058", ch: 5, sec: "5.6", page: 98, type: "concept", level: 2,
    q: "What does the gross system capacity from Eq. 5.20 leave out that may need to be added for the well or headgate?",
    opts: ["Net crop water need","Application efficiency of the low quarter","System downtime","On-farm conveyance losses"], a: 3,
    why: "Cg includes ELQ and downtime but not losses between the source and the field. Those are added with Qf = Qg / (Ec/100).",
    eq: "5.21", calc: "eq-5.21", fig: null, table: null },
  { id: "5-059", ch: 5, sec: "5.7", page: 99, type: "concept", level: 3,
    q: "When are idle time and downtime the same?",
    opts: ["When the cycle time equals the rotation time","When application time and set time are the same","When no rain falls during the cycle","They are never the same"], a: 1,
    why: "If some time is spent changing sets, downtime is larger than idle time. If the system runs continuously between sets, application time equals set time and the two match.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-060", ch: 5, sec: "5.7", page: 100, type: "concept", level: 2,
    q: "A furrow system runs a fixed 12-h set time all season. What problem does the book warn about?",
    opts: ["Under irrigation in the early season","Over irrigation and deep percolation when less water is needed, unless flow rates are adjusted","Excess drift on windy days","Higher pumping pressure late in the season"], a: 1,
    why: "An inflexible set time fitted to labor schedules applies the same depth even when SWD is small. The book warns this leads to over irrigation and deep percolation if flow is not adjusted.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-061", ch: 5, sec: "5.10", page: 101, type: "concept", level: 3,
    q: "Why might reducing deep percolation in a groundwater-irrigated region not conserve liquid water?",
    opts: ["The percolating water may recharge the aquifer it came from, so it was being recycled","Deep percolation never reaches the aquifer","Reducing deep percolation increases ET by the same amount","Pumping cost rises when efficiency improves"], a: 0,
    why: "Higher farm efficiency only saves water at the watershed scale if it reduces consumption or non-recoverable losses. Deep percolation to a usable aquifer is recoverable, though reducing it still helps water quality and energy.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-062", ch: 5, sec: "5.10", page: 102, type: "concept", level: 3,
    q: "To reduce aquifer depletion or increase stream flow in an agricultural watershed, what must change?",
    opts: ["Conveyance seepage must be stopped","Application efficiency must increase","Runoff must be eliminated","Consumptive use, mainly ET, must decrease"], a: 3,
    why: "Over long periods with steady groundwater levels, outflow is about precipitation minus ET. Only reducing consumptive use (ET) frees water, which may require reducing yield-producing ET.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-063", ch: 5, sec: "5.10", page: 102, type: "concept", level: 2,
    q: "Which is an example of the non-recoverable fraction?",
    opts: ["Deep percolation to a shallow aquifer used by neighbors","Water draining into a saline system or a very deep aquifer too costly to pump","Return flow to a river used downstream","Transpiration that produces yield"], a: 1,
    why: "Non-recoverable water is not consumed but not available for reuse. Return flows and shallow recharge are recoverable, and transpiration is the consumed fraction.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-064", ch: 5, sec: "5.10", page: 102, type: "concept", level: 2,
    q: "Watershed-scale conservation programs should target which fractions, according to the book?",
    opts: ["Application efficiency only","The recoverable fraction only","Runoff and drift only","The consumed fraction and/or the non-recoverable fraction"], a: 3,
    why: "Reducing recoverable losses only moves water that someone else would reuse. Real savings come from less consumption or fewer non-recoverable losses.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-065", ch: 5, sec: "5.3.1", page: 83, type: "calc", level: 1,
    q: "A pivot applies a gross depth of 2.4 in, and a soil check shows 1.8 in was stored in the root zone. What is the application efficiency?",
    opts: ["25%","133%","75%","67%"], a: 2,
    why: "Ea = dn / da × 100% = 1.8 / 2.4 × 100% = 75%. 133% inverts the ratio and 25% is the loss share.",
    eq: "5.1", calc: "eq-5.1", fig: null, table: null },
  { id: "5-066", ch: 5, sec: "5.3.1", page: 83, type: "calc", level: 1,
    q: "A sports complex applies 2.5 million gal of water, and 1.9 million gal is stored in the root zone. What is the application efficiency?",
    opts: ["76%","132%","24%","60%"], a: 0,
    why: "Ea = 1.9 / 2.5 × 100% = 76%. Volumes work as well as depths because the same area is in both. 24% is the share lost.",
    eq: "5.1", calc: "eq-5.1", fig: null, table: null },
  { id: "5-067", ch: 5, sec: "5.3.2", page: 83, type: "calc", level: 1,
    q: "A catch-can test gives a mean depth of 1.6 in and a low-quarter average of 1.1 in. What is the DU?",
    opts: ["0.31","1.45","0.69","0.50"], a: 2,
    why: "DU = dLQ / dz = 1.1 / 1.6 = 0.6875, about 0.69. 1.45 is the inverse (the scheduling coefficient) and 0.31 is 1 − DU.",
    eq: "5.2", calc: "eq-5.2", fig: null, table: null },
  { id: "5-068", ch: 5, sec: "5.3.2", page: 83, type: "calc", level: 2,
    q: "Eight equal-area cans catch 0.9, 1.1, 1.0, 0.7, 1.2, 0.8, 1.0, and 1.3 in. What is the DU?",
    opts: ["0.85","0.70","0.75","0.80"], a: 2,
    why: "The mean is 8.0 / 8 = 1.0 in. The lowest quarter is the 2 smallest cans, 0.7 and 0.8, averaging 0.75 in, so DU = 0.75. 0.70 uses only the single lowest can, and 0.85 is the CU of these data.",
    eq: "5.2", calc: "catch-can", fig: null, table: null },
  { id: "5-069", ch: 5, sec: "5.3.2", page: 84, type: "calc", level: 2,
    q: "Eight equal-area cans catch 0.9, 1.1, 1.0, 0.7, 1.2, 0.8, 1.0, and 1.3 in. What is Christiansen's CU?",
    opts: ["75%","85%","88%","15%"], a: 1,
    why: "Mean = 1.0 in. Absolute deviations are 0.1, 0.1, 0, 0.3, 0.2, 0.2, 0, 0.3, which sum to 1.2 in. CU = 100(1 − 1.2 / (8 × 1.0)) = 85%. 75% is the DU, and 15% is the average deviation ratio itself.",
    eq: "5.3", calc: "eq-5.3", fig: null, table: null },
  { id: "5-070", ch: 5, sec: "5.3.2", page: 84, type: "calc", level: 2,
    q: "A sprinkler test has a mean catch of 1.5 in and an average absolute deviation from the mean of 0.18 in. What is the CU?",
    opts: ["12%","82%","88%","92%"], a: 2,
    why: "CU = 100% × (1 − average deviation ÷ mean) = 100(1 − 0.18 / 1.5) = 88%. 82% subtracts 0.18 directly without dividing by the mean.",
    eq: "5.3", calc: "eq-5.3", fig: null, table: null },
  { id: "5-071", ch: 5, sec: "5.3.2", page: 84, type: "calc", level: 3,
    q: "A lateral move test gives 16 equal-area cans: 1.2, 1.1, 1.3, 0.9, 1.0, 1.0, 1.4, 0.8, 0.7, 0.9, 0.9, 0.8, 1.0, 0.9, 0.9, 1.2 in. What are DU and CU?",
    opts: ["DU = 0.80 and CU = 85%","DU = 0.85 and CU = 80%","DU = 0.70 and CU = 85%","DU = 0.80 and CU = 76%"], a: 0,
    why: "Mean = 16.0 / 16 = 1.0 in. The lowest 4 cans (0.7, 0.8, 0.8, 0.9) average 0.80 in, so DU = 0.80. The absolute deviations sum to 2.4 in, so CU = 100(1 − 2.4 / 16) = 85%. DU 0.70 uses only the lowest can.",
    eq: "5.3", calc: "catch-can", fig: null, table: null },
  { id: "5-072", ch: 5, sec: "5.3.2", page: 85, type: "calc", level: 3,
    q: "Three pivot cans catch 1.0, 0.8, and 1.2 in at 10, 20, and 30 ft from the pivot point. What is the Heermann and Hein CUH?",
    opts: ["84%","87%","90%","16%"], a: 0,
    why: "dz* = (10 + 16 + 36) / 60 = 1.033 in. Weighted deviations: 0.033×10 + 0.233×20 + 0.167×30 = 10.0. ΣdiSi = 62, so CUH = 100(1 − 10 / 62) = 83.9%, about 84%. 87% is the unweighted CU, which ignores that outer cans represent more area.",
    eq: "5.4", calc: "eq-5.4-5.5", fig: null, table: null },
  { id: "5-073", ch: 5, sec: "5.3.2", page: 86, type: "calc", level: 3,
    q: "Two pivot cans catch 0.9 in at 50 ft and 1.1 in at 150 ft from the pivot point. What is the weighted mean depth dz* used in CUH?",
    opts: ["1.05 in","1.00 in","1.10 in","0.95 in"], a: 0,
    why: "dz* = Σ(diSi) / ΣSi = (0.9×50 + 1.1×150) / 200 = 210 / 200 = 1.05 in. The simple average 1.00 in ignores that the outer can represents 3 times the area.",
    eq: "5.5", calc: "eq-5.4-5.5", fig: null, table: null },
  { id: "5-074", ch: 5, sec: "5.3.4", page: 87, type: "calc", level: 1,
    q: "A sprinkler applies a gross depth of 1.25 in. Runoff is 0.05 in and evaporation plus drift is 0.10 in. What is the average depth infiltrated?",
    opts: ["1.20 in","1.40 in","1.10 in","1.15 in"], a: 2,
    why: "dz = dg − dr − dev = 1.25 − 0.05 − 0.10 = 1.10 in. 1.40 in adds the losses instead of subtracting them, and the others subtract only one loss.",
    eq: "5.7", calc: "eq-5.6-5.7", fig: null, table: null },
  { id: "5-075", ch: 5, sec: "5.3.4", page: 87, type: "calc", level: 2,
    q: "A system applied 1.5 in gross. The average infiltrated depth was 1.38 in and runoff was 0.04 in. How much was lost to evaporation and drift?",
    opts: ["0.16 in","0.12 in","0.08 in","0.04 in"], a: 2,
    why: "From Eq. 5.6, dev = dg − dz − dr = 1.5 − 1.38 − 0.04 = 0.08 in. 0.12 in forgets to remove runoff, and 0.16 in adds runoff instead.",
    eq: "5.6", calc: "eq-5.6-5.7", fig: null, table: null },
  { id: "5-076", ch: 5, sec: "5.3.4", page: 87, type: "calc", level: 1,
    q: "A system has a DU of 0.82 and an average infiltrated depth of 1.4 in. What is the average low-quarter depth?",
    opts: ["1.15 in","1.71 in","1.40 in","0.25 in"], a: 0,
    why: "dLQ = DU × dz = 0.82 × 1.4 = 1.148, about 1.15 in. 1.71 in divides by DU instead of multiplying.",
    eq: "5.8", calc: "eq-5.8", fig: null, table: null },
  { id: "5-077", ch: 5, sec: "5.3.4", page: 88, type: "calc", level: 2,
    q: "DU = 0.80, dz = 1.5 in, SWD = 1.4 in, and da = 1.65 in with no runoff recovery. What is ELQ?",
    opts: ["91%","85%","73%","80%"], a: 2,
    why: "dLQ = 0.80 × 1.5 = 1.2 in, which is less than SWD, so de = 1.2 in (Eq. 5.9). ELQ = 1.2 / 1.65 × 100% = 72.7%, about 73%. 85% wrongly uses SWD as de, and 91% uses dz.",
    eq: "5.11", calc: "eq-5.9-5.11", fig: null, table: null },
  { id: "5-078", ch: 5, sec: "5.3.4", page: 88, type: "calc", level: 3,
    q: "DU = 0.85, dz = 1.6 in, SWD = 1.0 in, and da = 1.75 in. What is ELQ?",
    opts: ["91%","78%","57%","85%"], a: 2,
    why: "dLQ = 0.85 × 1.6 = 1.36 in, which is more than SWD, so de = SWD = 1.0 in (Eq. 5.10). ELQ = 1.0 / 1.75 = 57%. 78% uses dLQ as de, which counts water the root zone cannot hold.",
    eq: "5.10", calc: "eq-5.9-5.11", fig: null, table: null },
  { id: "5-079", ch: 5, sec: "5.3.4", page: 88, type: "calc", level: 3,
    q: "A turf field gets da = 1.0 in from the source. SWD = 0.75 in, and runoff plus evaporation and drift is 0.08 in. If infiltration were perfectly uniform, what would ELQ be?",
    opts: ["82%","92%","75%","100%"], a: 2,
    why: "dz = 1.0 − 0.08 = 0.92 in, and with DU = 1 dLQ = 0.92 in, which exceeds SWD. So de = 0.75 in and ELQ = 0.75 / 1.0 = 75%. 92% uses dz, and 82% divides by dz instead of da.",
    eq: "5.11", calc: "eq-5.9-5.11", fig: null, table: null },
  { id: "5-080", ch: 5, sec: "5.3.4", page: 89, type: "calc", level: 2,
    q: "A closed runoff recovery system on a furrow field has dg = 4.5 in, runoff ratio Rr = 0.25, and return ratio Rt = 0.8. What depth came from the original source?",
    opts: ["4.50 in","3.75 in","3.38 in","3.60 in"], a: 3,
    why: "Closed system: da = dg(1 − Rr Rt) = 4.5(1 − 0.20) = 3.60 in. 3.75 in is the open system formula, and 3.38 in subtracts all runoff, not the reused part.",
    eq: "5.12a", calc: "eq-5.12", fig: null, table: null },
  { id: "5-081", ch: 5, sec: "5.3.4", page: 89, type: "calc", level: 3,
    q: "An open runoff recovery system (runoff reused on a different field) has dg = 4.5 in, Rr = 0.25, and Rt = 0.8. What is da for the field?",
    opts: ["3.75 in","3.60 in","5.40 in","3.38 in"], a: 0,
    why: "Open system: da = dg / (1 + Rr Rt) = 4.5 / 1.20 = 3.75 in. 3.60 in is the closed system result and 5.40 in multiplies instead of dividing.",
    eq: "5.12b", calc: "eq-5.12", fig: null, table: null },
  { id: "5-082", ch: 5, sec: "5.3.5", page: 90, type: "calc", level: 1,
    q: "A turf audit gives an average catch of 1.2 in and a low-quarter average of 0.9 in. What is the scheduling coefficient?",
    opts: ["0.75","1.33","1.25","0.30"], a: 1,
    why: "SC = dz / dLQ = 1.2 / 0.9 = 1.33. 0.75 is the DU, the inverse of SC.",
    eq: "5.13", calc: "eq-5.13", fig: null, table: null },
  { id: "5-083", ch: 5, sec: "5.3.5", page: 90, type: "calc", level: 2,
    q: "A lawn needs 0.75 in. The sprinklers apply 0.4 in/hr on average and the SC is 1.3. How long should they run so about 90% of the lawn is adequately watered?",
    opts: ["2.4 hr","1.9 hr","1.4 hr","3.0 hr"], a: 0,
    why: "Uniform run time = 0.75 / 0.4 = 1.875 hr. Multiply by SC: 1.875 × 1.3 = 2.44 hr, about 2.4 hr. 1.9 hr ignores nonuniformity and 1.4 hr divides by SC.",
    eq: "5.13", calc: "eq-5.13", fig: null, table: null },
  { id: "5-084", ch: 5, sec: "5.3.5", page: 90, type: "calc", level: 2,
    q: "A sod farm sprinkler ran 6 hr during a test with DU = 0.75. How long would it need to run for the same result if the pattern were perfectly uniform?",
    opts: ["4.5 hr","8.0 hr","6.0 hr","5.3 hr"], a: 0,
    why: "SC = 1 / 0.75 = 1.33, and time = 6 / 1.33 = 4.5 hr (as in Example 5.4). 8.0 hr multiplies by SC instead of dividing.",
    eq: "5.13", calc: "eq-5.13", fig: null, table: null },
  { id: "5-085", ch: 5, sec: "5.3.6", page: 90, type: "calc", level: 2,
    q: "An irrigation infiltrates an average 2.5 in on 1 ac with CU = 80% (F1 = 0.64 from Table 5.1). What is the deep percolation from nonuniformity?",
    opts: ["1.60 ac-in","0.90 ac-in","0.50 ac-in","0.64 ac-in"], a: 1,
    why: "Vdp1 = Vz(1 − F1) = 2.5 × 1 × (1 − 0.64) = 0.90 ac-in. 1.60 ac-in is Vz × F1, the part that does not percolate.",
    eq: "5.14", calc: "eq-5.14", fig: null, table: "5.1" },
  { id: "5-086", ch: 5, sec: "5.3.6", page: 90, type: "calc", level: 3,
    q: "A 125-ac field receives an average infiltrated depth of 1.5 in with CU = 88% (F1 = 0.78). What is Vdp1?",
    opts: ["0.33 ac-in","146 ac-in (12.2 ac-ft)","41 ac-ft","41 ac-in (3.4 ac-ft)"], a: 3,
    why: "Vz = 1.5 × 125 = 187.5 ac-in, and Vdp1 = 187.5 × (1 − 0.78) = 41.25 ac-in, about 3.4 ac-ft. 146 ac-in uses F1 instead of 1 − F1, and 41 ac-ft mixes units.",
    eq: "5.14", calc: "eq-5.14", fig: null, table: "5.1" },
  { id: "5-087", ch: 5, sec: "5.3.6", page: 90, type: "calc", level: 1,
    q: "On 1 ac, dLQ = 1.6 in and SWD = 1.2 in. What is the deep percolation from excessive application (Vdp2)?",
    opts: ["0.42 ac-in","0.40 ac-in","0.38 ac-in","1.14 ac-in"], a: 2,
    why: "Vdp2 ≈ 0.95 A(dLQ − SWD) = 0.95 × 1 × 0.4 = 0.38 ac-in. 0.40 ac-in leaves out the 0.95 factor, and 0.42 divides by it.",
    eq: "5.15", calc: "eq-5.15", fig: null, table: null },
  { id: "5-088", ch: 5, sec: "5.3.6", page: 90, type: "calc", level: 1,
    q: "A 40-ac field has Vdp1 = 15 ac-in and Vdp2 = 9 ac-in for one irrigation. What is the depth of deep percolation?",
    opts: ["24 in","0.15 in","0.38 in","0.60 in"], a: 3,
    why: "Vdp = 15 + 9 = 24 ac-in, and dp = Vdp / A = 24 / 40 = 0.60 in. 0.38 in uses Vdp1 only and 24 in forgets to divide by area.",
    eq: "5.17", calc: "eq-5.16-5.17", fig: null, table: null },
  { id: "5-089", ch: 5, sec: "5.3.6", page: 91, type: "calc", level: 1,
    q: "Leachate below the root zone has 25 ppm nitrate-N and deep percolation is 0.6 in. How much nitrate-N is lost?",
    opts: ["0.34 lb/ac","15 lb/ac","3.4 lb/ac","6.6 lb/ac"], a: 2,
    why: "Cl = 0.226 C dp = 0.226 × 25 × 0.6 = 3.39, about 3.4 lb/ac. 15 lb/ac leaves out the 0.226 factor.",
    eq: "5.18", calc: "eq-5.18", fig: null, table: null },
  { id: "5-090", ch: 5, sec: "5.3.6", page: 91, type: "calc", level: 3,
    q: "For 1 ac: dz = 1.8 in, CU = 86% (F1 = 0.75), DU = 0.78, SWD = 1.1 in, and leachate nitrate-N = 15 ppm. How much nitrate-N leaches this irrigation?",
    opts: ["1.5 lb/ac","2.5 lb/ac","3.8 lb/ac","1.0 lb/ac"], a: 1,
    why: "Vdp1 = 1.8(1 − 0.75) = 0.45 ac-in. dLQ = 0.78 × 1.8 = 1.40 in, so Vdp2 = 0.95(1.40 − 1.1) = 0.29 ac-in. dp = 0.74 in and Cl = 0.226 × 15 × 0.74 = 2.5 lb/ac. 1.5 lb/ac uses only Vdp1 and 3.8 lb/ac uses dz instead of dLQ in Eq. 5.15.",
    eq: "5.18", calc: "leaching-procedure", fig: null, table: "5.1" },
  { id: "5-091", ch: 5, sec: "5.3.7", page: 92, type: "calc", level: 1,
    q: "A canal diverts the equivalent of 3.0 in over the served area, and 2.4 in is delivered and applied to the fields. What is the conveyance efficiency?",
    opts: ["125%","80%","20%","72%"], a: 1,
    why: "Ec = da / ds × 100% = 2.4 / 3.0 = 80%. 125% inverts the ratio and 20% is the loss.",
    eq: "5.19", calc: "eq-5.19", fig: null, table: null },
  { id: "5-092", ch: 5, sec: "5.3.7", page: 92, type: "calc", level: 1,
    q: "A project has supply conveyance efficiency Ec = 80% and field canal efficiency Eb = 70%. What is the distribution efficiency?",
    opts: ["150%","75%","88%","56%"], a: 3,
    why: "Ed = Ec × Eb = 0.80 × 0.70 = 0.56, or 56%. Averaging (75%) or dividing (88%) the two efficiencies is not how losses in series combine.",
    eq: null, calc: "project-efficiency", fig: null, table: null },
  { id: "5-093", ch: 5, sec: "5.3.7", page: 92, type: "calc", level: 2,
    q: "A farm has field canal efficiency Eb = 90% and field application efficiency Ea = 75%. What is the farm efficiency?",
    opts: ["68%","83%","60%","75%"], a: 0,
    why: "Ef = Ea × Eb = 0.75 × 0.90 = 0.675, about 68%. 83% divides the two, and 75% ignores the canal losses.",
    eq: null, calc: "project-efficiency", fig: null, table: null },
  { id: "5-094", ch: 5, sec: "5.3.7", page: 94, type: "calc", level: 3,
    q: "An unlined ditch in loam (seepage about 1.4 ft³/ft²/d) is 2,640 ft long with 3.0 ft² of wetted area per ft and runs 150 d/yr. What is the seepage loss?",
    opts: ["13 ac-ft/yr","3.2 ac-ft/yr","76 ac-ft/yr","38 ac-ft/yr"], a: 3,
    why: "Seepage = 3.0 × 2,640 × 1.4 × 150 / 43,560 = 38.2 ac-ft/yr. 3.2 divides by 12 as if the answer were ac-in, and 13 forgets the wetted area per foot.",
    eq: null, calc: "ditch-seepage", fig: "5.8", table: null },
  { id: "5-095", ch: 5, sec: "5.3.7", page: 94, type: "calc", level: 3,
    q: "A half-mile (2,640 ft) ditch carries 3 cfs for 150 d with ditch side vegetation losing 1% of the flow per mile. What is the seasonal vegetation loss? (Use 1 cfs ≈ 1 ac-in/hr.)",
    opts: ["9.0 ac-ft","4.5 ac-ft","54 ac-ft","0.36 ac-ft"], a: 1,
    why: "Loss rate = 0.01 × 3 cfs × 0.5 mile × 24 hr/d = 0.36 ac-in/d. Over 150 d that is 54 ac-in, or 4.5 ac-ft. 9.0 ac-ft uses a full mile and 54 ac-ft forgets to divide by 12.",
    eq: null, calc: "ditch-seepage", fig: null, table: null },
  { id: "5-096", ch: 5, sec: "5.5", page: 95, type: "calc", level: 2,
    q: "A system needs a net capacity of 0.25 in/d. ELQ is 80% and downtime is 10%. What gross capacity is required?",
    opts: ["0.35 in/d","0.31 in/d","0.18 in/d","0.28 in/d"], a: 0,
    why: "Cg = Cn / [(ELQ/100)(1 − Dt/100)] = 0.25 / (0.80 × 0.90) = 0.347, about 0.35 in/d. 0.31 in/d ignores downtime and 0.18 in/d multiplies instead of dividing.",
    eq: "5.20", calc: "eq-5.20", fig: null, table: null },
  { id: "5-097", ch: 5, sec: "5.5", page: 95, type: "calc", level: 3,
    q: "A 130-ac field needs a net capacity of 6.0 gpm/ac. ELQ is 85% and downtime is 5%. What gross flow rate does the system need?",
    opts: ["About 920 gpm","About 970 gpm","About 630 gpm","About 7.4 gpm"], a: 1,
    why: "Cg = 6.0 / (0.85 × 0.95) = 7.43 gpm/ac, and Qg = 7.43 × 130 = 966 gpm, about 970 gpm. 920 gpm ignores downtime and 630 gpm multiplies by the efficiencies.",
    eq: "5.20", calc: "eq-5.20", fig: null, table: null },
  { id: "5-098", ch: 5, sec: "5.5", page: 95, type: "calc", level: 1,
    q: "Peak net crop need is 0.28 in/d. What is that in gpm/ac?",
    opts: ["7.6 gpm/ac","127 gpm/ac","0.015 gpm/ac","5.3 gpm/ac"], a: 3,
    why: "0.28 in/d × 18.86 gpm/ac per in/d = 5.28, about 5.3 gpm/ac. 127 gpm/ac uses 452 gpm per ac-in/hr without dividing by 24 hr/d, and 0.015 divides by 18.86.",
    eq: "5.20", calc: "eq-5.20", fig: null, table: null },
  { id: "5-099", ch: 5, sec: "5.6", page: 97, type: "calc", level: 3,
    q: "A well delivers 800 gpm to a 125-ac pivot with ELQ = 85% and no downtime. About what net capacity does it supply?",
    opts: ["0.24 in/d","0.34 in/d","0.40 in/d","0.29 in/d"], a: 3,
    why: "800 / 125 = 6.4 gpm/ac, which is 6.4 / 18.86 = 0.34 in/d gross. Net = 0.34 × 0.85 = 0.29 in/d. 0.34 in/d is the gross value and 0.40 divides by ELQ.",
    eq: "5.20", calc: "cn-from-flow", fig: null, table: null },
  { id: "5-100", ch: 5, sec: "5.6", page: 98, type: "calc", level: 1,
    q: "A field needs a gross flow of 900 gpm and is fed through an earthen lateral with Ec = 85%. What flow must enter the lateral?",
    opts: ["About 985 gpm","About 765 gpm","About 1,060 gpm","900 gpm"], a: 2,
    why: "Qf = Qg / (Ec/100) = 900 / 0.85 = 1,059 gpm. 765 gpm multiplies by Ec, which would deliver too little.",
    eq: "5.21", calc: "eq-5.21", fig: null, table: null },
  { id: "5-101", ch: 5, sec: "5.6", page: 99, type: "calc", level: 3,
    q: "Net capacity is 0.25 in/d, ELQ = 80%, and downtime = 5%. Field 1 (60 ac) is served through a lateral with Ec = 85%, Field 2 (100 ac) through one with Ec = 95%, and both laterals come off a main canal with Ec = 90%. What must the source supply?",
    opts: ["About 1,210 gpm","About 1,090 gpm","About 990 gpm","About 1,350 gpm"], a: 0,
    why: "Cn = 0.25 × 18.86 = 4.72 gpm/ac and Cg = 4.72 / (0.80 × 0.95) = 6.20 gpm/ac. Field flows are 372 and 620 gpm. Through the laterals, 372 / 0.85 + 620 / 0.95 = 438 + 653 = 1,091 gpm. Through the main canal, 1,091 / 0.90 = 1,212 gpm. 1,090 gpm forgets the main canal and 990 gpm ignores all conveyance losses.",
    eq: "5.21", calc: "farm-capacity", fig: null, table: null },
  { id: "5-102", ch: 5, sec: "5.5", page: 95, type: "calc", level: 3,
    q: "A golf course needs a net capacity of 1.5 million gal/d. ELQ is 70% and the system is down 15% of the time. What gross capacity is required?",
    opts: ["0.89 million gal/d","2.1 million gal/d","1.8 million gal/d","2.5 million gal/d"], a: 3,
    why: "Cg = 1.5 / (0.70 × 0.85) = 2.52 million gal/d. 2.1 ignores downtime, 1.8 ignores ELQ, and 0.89 multiplies instead of dividing.",
    eq: "5.20", calc: "eq-5.20", fig: null, table: null },
  { id: "5-103", ch: 5, sec: "5.6", page: 97, type: "calc", level: 2,
    q: "The peak 10-d irrigation requirement is 3.3 in per 10 d. What net capacity is this in gpm/ac?",
    opts: ["0.33 gpm/ac","62 gpm/ac","6.2 gpm/ac","1.7 gpm/ac"], a: 2,
    why: "3.3 in / 10 d = 0.33 in/d, and 0.33 × 18.86 = 6.22 gpm/ac, as the book shows. 62 gpm/ac forgets to divide by 10 d.",
    eq: "5.20", calc: "eq-5.20", fig: "5.10", table: null },
  { id: "5-104", ch: 5, sec: "5.6", page: 97, type: "calc", level: 2,
    q: "A 130-ac field needs a net capacity of 6.22 gpm/ac at peak. With ELQ = 85% and no downtime, what gross flow is needed?",
    opts: ["About 810 gpm","About 950 gpm","About 690 gpm","About 1,100 gpm"], a: 1,
    why: "Net flow = 6.22 × 130 = 809 gpm. Gross = 809 / 0.85 = 951 gpm, matching the book's approximately 950 gpm. 810 gpm is the net flow and 690 gpm multiplies by 0.85.",
    eq: "5.20", calc: "eq-5.20", fig: "5.10", table: null },
  { id: "5-105", ch: 5, sec: "5.3.1", page: 82, type: "figure", level: 1,
    q: "In Figure 5.4, which loss takes water below the crop root zone?",
    opts: ["Drift","Deep percolation","Runoff","Canopy evaporation"], a: 1,
    why: "Figure 5.4 shows deep percolation as drops leaving the bottom of the root zone. Drift, droplet and canopy evaporation leave through the air, and runoff leaves over the surface.",
    eq: null, calc: null, fig: "5.4", table: null },
  { id: "5-106", ch: 5, sec: "5.3.3", page: 86, type: "figure", level: 2,
    q: "Using Figure 5.6 (data of Example 5.1), what percent of the field receives at least 1.6 in?",
    opts: ["95%","80%","90%","75%"], a: 2,
    why: "The point at 1.6 in sits at a fraction of 0.90 of the field area, so 90% is adequately irrigated for a 1.6 in desired depth. Only the last 2 points (1.4 and 1.2 in) fall short.",
    eq: null, calc: null, fig: "5.6", table: null },
  { id: "5-107", ch: 5, sec: "5.3.3", page: 86, type: "figure", level: 2,
    q: "Using Figure 5.6, if the desired depth were 2.0 in, about what share of the field would be adequately irrigated?",
    opts: ["55%","45%","75%","90%"], a: 0,
    why: "Points at 2.0 in occur at 0.45, 0.50 and 0.55 of the field area, and the next point (0.60) drops to 1.9 in. So about 55% gets 2.0 in or more.",
    eq: null, calc: null, fig: "5.6", table: null },
  { id: "5-108", ch: 5, sec: "5.3.3", page: 86, type: "figure", level: 1,
    q: "In Figure 5.6, what depth does 100% of the field receive or more?",
    opts: ["1.2 in","1.4 in","1.6 in","2.9 in"], a: 0,
    why: "The last point at a fraction of 1.0 is 1.2 in, the smallest can. 2.9 in is the depth that only 5% of the field receives.",
    eq: null, calc: null, fig: "5.6", table: null },
  { id: "5-109", ch: 5, sec: "5.3.4", page: 88, type: "figure", level: 3,
    q: "In Figure 5.7c (nonuniform, no excess), what causes the deep percolation?",
    opts: ["Irrigating too frequently","Excessive application with uniform infiltration","Runoff from the low end of the field","Nonuniform infiltration, with dLQ = SWD = de"], a: 3,
    why: "In 5.7c the low-quarter depth just equals SWD, so the percolation over most of the field (about 90%) comes from nonuniformity, not from applying too much on average.",
    eq: null, calc: null, fig: "5.7", table: null },
  { id: "5-110", ch: 5, sec: "5.3.4", page: 88, type: "figure", level: 2,
    q: "In Figure 5.7b (uniform, excess application), what is the effective depth?",
    opts: ["de = 0","de = dz","de = dLQ","de = SWD"], a: 3,
    why: "With uniform infiltration dLQ = dz, but infiltration is more than SWD, so only SWD can be stored. de = SWD and the rest is deep percolation from excess application.",
    eq: null, calc: null, fig: "5.7", table: null },
  { id: "5-111", ch: 5, sec: "5.3.4", page: 88, type: "figure", level: 3,
    q: "Figure 5.7d shows deep percolation with both causes. How is it divided?",
    opts: ["All percolation below SWD is from nonuniformity","Water above SWD is runoff, water below dLQ is excess","Water between SWD and dLQ is the excess part, water below dLQ is the nonuniform part","Water below dz is excess, water above dz is nonuniform"], a: 2,
    why: "In 5.7d the band from SWD down to the dLQ line is labeled excess application, and the extra infiltration beyond dLQ is labeled nonuniform. de still equals SWD.",
    eq: null, calc: null, fig: "5.7", table: null },
  { id: "5-112", ch: 5, sec: "5.3.7", page: 93, type: "figure", level: 2,
    q: "From Figure 5.8, about what seepage rate applies to a ditch in sand or gravelly sandy loam?",
    opts: ["About 0.55 to 0.75 ft³/ft²/d","About 0.2 to 0.3 ft³/ft²/d","About 3.3 to 5.75 ft³/ft²/d","About 1.65 to 2.2 ft³/ft²/d"], a: 3,
    why: "The sand and gravelly sandy loam band meets the curve at roughly 1.65 to 2.2 ft³/ft²/d. 0.2 to 0.3 is concrete, 3.3 to 5.75 is gravel, and 0.55 to 0.75 is clay loam or silt loam.",
    eq: null, calc: "ditch-seepage", fig: "5.8", table: null },
  { id: "5-113", ch: 5, sec: "5.3.7", page: 93, type: "figure", level: 3,
    q: "A new concrete-lined ditch (about 0.2 ft³/ft²/d from Figure 5.8) is 10 miles long, has 3 ft² of wetted area per ft, and runs 200 d/yr. What is the seepage loss?",
    opts: ["About 12 ac-ft/yr","About 1,020 ac-ft/yr","About 145 ac-ft/yr","About 1,750 ac-ft/yr"], a: 2,
    why: "Length = 52,800 ft. Seepage = 3 × 52,800 × 0.2 × 200 / 43,560 = 145 ac-ft/yr. 1,020 ac-ft uses the loam rate of 1.4, and 12 ac-ft divides by 12 as if it were ac-in.",
    eq: null, calc: "ditch-seepage", fig: "5.8", table: null },
  { id: "5-114", ch: 5, sec: "5.6", page: 96, type: "figure", level: 1,
    q: "In Figure 5.9, how does the net system capacity compare with the average crop ET for the period?",
    opts: ["They are equal at 0.25 in/d","0.275 in/d capacity versus 0.25 in/d average ET","0.50 in/d capacity versus 0.25 in/d average ET","0.25 in/d capacity versus 0.275 in/d average ET"], a: 3,
    why: "The flat line is a net capacity of 0.25 in/d while average ET is 0.275 in/d. Shortage periods above the line must come from soil water or rain, and surplus periods below it refill the soil.",
    eq: null, calc: null, fig: "5.9", table: null },
  { id: "5-115", ch: 5, sec: "5.6", page: 97, type: "figure", level: 2,
    q: "In Figure 5.10, about how deep does cumulative soil water depletion get with a 500 gpm supply, and how does that compare with the 3 in AD?",
    opts: ["About 0.5 in, almost no depletion","About 1.25 in, well within the allowable depletion","About 3 in, exactly at the allowable depletion","About 4 in, which is below the allowable depletion"], a: 3,
    why: "The 500 gpm depletion curve levels off near −4.1 in in August, passing the −3 in AD line in late July, so the crop would be stressed. 1.25 in is the depletion for 700 gpm.",
    eq: null, calc: null, fig: "5.10", table: null },
  { id: "5-116", ch: 5, sec: "5.6", page: 97, type: "figure", level: 2,
    q: "In Figure 5.10, when does the largest 10-d deficit (ET minus rain) occur and about how large is it?",
    opts: ["Late May, about 1.2 in","Mid-July, about 3.3 in","Mid-June, about 1.9 in","Late August, about 2.2 in"], a: 1,
    why: "The tallest deficit bar is in mid-July at about −3.3 in, which the text converts to 6.24 gpm/ac of net capacity for that 10-d period.",
    eq: null, calc: null, fig: "5.10", table: null },
  { id: "5-117", ch: 5, sec: "5.6", page: 98, type: "figure", level: 3,
    q: "A loamy sand holds 1.0 in/ft and corn roots to 4 ft with fdc = 0.5. Using Figure 5.11 at the 95% probability level, about what net capacity is needed?",
    opts: ["About 0.27 in/d","About 0.19 in/d","About 0.25 in/d","About 0.22 in/d"], a: 2,
    why: "AD = 1.0 × 4 × 0.5 = 2.0 in. The 95% curve at 2.0 in reads about 0.245 in/d. 0.19 in/d is the 50% curve, 0.27 in/d is the 99% curve, and 0.22 in/d is the 95% reading at 3 in AD.",
    eq: null, calc: null, fig: "5.11", table: null },
  { id: "5-118", ch: 5, sec: "5.6", page: 98, type: "figure", level: 2,
    q: "In Figure 5.11, what net capacity does the 50% probability curve give at a management allowed depletion of 4 in?",
    opts: ["About 0.20 in/d","About 0.14 in/d","About 0.23 in/d","About 0.10 in/d"], a: 1,
    why: "The 50% curve passes about 0.135 in/d at 4 in. 0.20 in/d is the 95% curve and 0.23 in/d the 99% curve at the same depletion.",
    eq: null, calc: null, fig: "5.11", table: null },
  { id: "5-119", ch: 5, sec: "5.6", page: 98, type: "figure", level: 1,
    q: "In the farm layout of Figure 5.12, water for which field passes through both the concrete canal and the earth canal?",
    opts: ["Neither field","Field 2","Both fields","Field 1"], a: 3,
    why: "Field 2 takes water directly from the concrete canal (Ec = 90%). Field 1 is fed by the earth canal (Ec = 80%) that branches off the concrete canal, so its water passes both.",
    eq: null, calc: null, fig: "5.12", table: null },
  { id: "5-120", ch: 5, sec: "5.10", page: 102, type: "figure", level: 2,
    q: "In the watershed water balance of Figure 5.13, which flows are consumptive use?",
    opts: ["Inflow and outflow","Deep percolation and groundwater flow","Runoff and runoff reuse","Irrigated, dryland and riparian ET and evaporation"], a: 3,
    why: "ET and evaporation leave the watershed as vapor and are not returned. Deep percolation, runoff and return flows stay in the system and can be reused downstream.",
    eq: null, calc: null, fig: "5.13", table: null },
  { id: "5-121", ch: 5, sec: "5.3.6", page: 90, type: "table", level: 1,
    q: "From Table 5.1, what is F1 for a CU of 78%?",
    opts: ["0.58","0.62","0.60","0.78"], a: 2,
    why: "Table 5.1 gives F1 = 0.60 at CU 78. 0.62 is for CU 79 and 0.58 for CU 77.",
    eq: null, calc: "tab-5.1", fig: null, table: "5.1" },
  { id: "5-122", ch: 5, sec: "5.3.6", page: 90, type: "table", level: 2,
    q: "Table 5.1 lists CU 90 and 92 but not 91. What F1 should you use for CU = 91%?",
    opts: ["0.91","0.82","0.86","About 0.84"], a: 3,
    why: "Interpolate between 0.82 at CU 90 and 0.86 at CU 92, giving 0.84. 0.91 confuses F1 with CU.",
    eq: null, calc: "tab-5.1", fig: null, table: "5.1" },
  { id: "5-123", ch: 5, sec: "5.3.6", page: 90, type: "table", level: 3,
    q: "Using Table 5.1, with CU = 75% what share of the infiltrated water percolates below the root zone because of nonuniformity at 90% adequacy?",
    opts: ["55%","45%","25%","75%"], a: 1,
    why: "F1 = 0.55 at CU 75, and Vdp1 / Vz = 1 − F1 = 0.45, or 45%. 55% is F1 itself.",
    eq: "5.14", calc: "eq-5.14", fig: null, table: "5.1" },
  { id: "5-124", ch: 5, sec: "5.3.7", page: 93, type: "table", level: 1,
    q: "From Table 5.2, what conveyance efficiency applies to a continuous supply with no substantial change in flow?",
    opts: ["90%","80%","70%","65%"], a: 0,
    why: "Continuous supply gets 90%. Rotational supply with effective management on 7,000 to 15,000 ac projects gets 80%, and poorly managed rotational supply 70% or 65%.",
    eq: null, calc: "tab-5.2", fig: null, table: "5.2" },
  { id: "5-125", ch: 5, sec: "5.3.7", page: 93, type: "table", level: 1,
    q: "From Table 5.2, what field canal efficiency applies to irrigated blocks smaller than 50 ac with unlined canals?",
    opts: ["90%","80%","70%","65%"], a: 2,
    why: "Small blocks with unlined canals get 70%, and with lined canals or pipelines 80%. Blocks larger than 50 ac get 80% unlined and 90% lined.",
    eq: null, calc: "tab-5.2", fig: null, table: "5.2" },
  { id: "5-126", ch: 5, sec: "5.3.7", page: 93, type: "table", level: 2,
    q: "From Table 5.2, what field canal efficiency applies to a rotational delivery system with insufficient management and communication?",
    opts: ["65%","55%","30%","40%"], a: 3,
    why: "The rotational rows are adequate 65%, sufficient 55%, insufficient 40%, and poor 30%.",
    eq: null, calc: "tab-5.2", fig: null, table: "5.2" },
  { id: "5-127", ch: 5, sec: "5.3.7", page: 93, type: "table", level: 3,
    q: "A 10,000-ac rotational project with 400-ac rotational areas is well managed, and its fields are blocks larger than 50 ac on lined canals. Using Table 5.2, what is the distribution efficiency?",
    opts: ["72%","90%","80%","64%"], a: 0,
    why: "Ec = 80% (rotational, 7,000 to 15,000 ac, effective management) and Eb = 90% (blocks over 50 ac, lined). Ed = 0.80 × 0.90 = 72%. 64% uses 80% for both.",
    eq: null, calc: "project-efficiency", fig: null, table: "5.2" },
  { id: "5-128", ch: 5, sec: "5.6", page: 96, type: "table", level: 1,
    q: "Using Table 5.3, a crop has a maximum monthly ET of 9 in/mo and the allowable depletion is 2.0 in. What is the peak daily ET?",
    opts: ["0.33 in/d","0.30 in/d","0.37 in/d","0.35 in/d"], a: 3,
    why: "The 2.0 in row under 9 in/mo reads 0.35 in/d. A simple 9 / 30 = 0.30 in/d understates the peak, and 0.37 is the 1.0 in row.",
    eq: null, calc: "tab-5.3", fig: null, table: "5.3" },
  { id: "5-129", ch: 5, sec: "5.6", page: 96, type: "table", level: 2,
    q: "For a maximum monthly ET of 10 in/mo, Table 5.3 gives what peak daily ET at an allowable depletion of 1.0 in and of 4.0 in?",
    opts: ["0.37 in/d and 0.42 in/d","0.42 in/d and 0.37 in/d","0.33 in/d for both","0.39 in/d and 0.36 in/d"], a: 1,
    why: "The 10 in/mo column reads 0.42 at 1.0 in and 0.37 at 4.0 in. A smaller soil reservoir cannot buffer short hot spells, so the design peak is higher.",
    eq: null, calc: "tab-5.3", fig: null, table: "5.3" },
  { id: "5-130", ch: 5, sec: "5.6", page: 96, type: "table", level: 3,
    q: "Maximum monthly ET is 8 in/mo and the allowable depletion is 3.0 in. Using Table 5.3, what net capacity in gpm/ac would meet the peak daily ET?",
    opts: ["About 0.30 gpm/ac","About 5.0 gpm/ac","About 6.2 gpm/ac","About 5.7 gpm/ac"], a: 3,
    why: "Table 5.3 gives 0.30 in/d for 8 in/mo and 3.0 in AD. 0.30 × 18.86 = 5.66 gpm/ac. 5.0 gpm/ac converts the monthly average 8 / 30 = 0.27 in/d instead of the peak.",
    eq: null, calc: "tab-5.3", fig: null, table: "5.3" },
  { id: "5-131", ch: 5, sec: "5.8", page: 100, type: "table", level: 1,
    q: "From Table 5.4, what pressure range is typical for a center pivot?",
    opts: ["70 to 100 psi","50 to 70 psi","20 to 70 psi","0.5 to 10 psi"], a: 2,
    why: "Center pivots run at 20 to 70 psi. Hand move, solid-set and side roll need 50 to 70 psi, travelers 70 to 100 psi, and gated pipe 0.5 to 10 psi.",
    eq: null, calc: "tab-5.4", fig: null, table: "5.4" },
  { id: "5-132", ch: 5, sec: "5.8", page: 100, type: "table", level: 1,
    q: "From Table 5.4, which system has the highest labor requirement per acre per irrigation?",
    opts: ["Solid-set, 0.05 to 0.1 hr/ac/irrig","Center pivot, 0.05 to 0.15 hr/ac/irrig","Hand move sprinklers and furrow siphon tubes, up to 1.5 hr/ac/irrig","Linear move, 0.1 to 0.3 hr/ac/irrig"], a: 2,
    why: "Hand move (0.5 to 1.5) and siphon tubes (1.0 to 1.5) reach 1.5 hr/ac/irrig. Pivots and solid-set need the least labor.",
    eq: null, calc: "tab-5.4", fig: null, table: "5.4" },
  { id: "5-133", ch: 5, sec: "5.8", page: 100, type: "table", level: 2,
    q: "A field has slopes up to 12%. According to Table 5.4, which of these systems is within its typical maximum slope?",
    opts: ["Linear move (5 to 8%)","Center pivot (10 to 20%)","Side roll and towline (10%)","Boom (5%)"], a: 1,
    why: "Center pivots handle 10 to 20% slopes. Linear move, side roll and boom limits are all below 12%. Furrow systems are limited to 2%.",
    eq: null, calc: "tab-5.4", fig: null, table: "5.4" },
  { id: "5-134", ch: 5, sec: "5.8", page: 101, type: "table", level: 2,
    q: "According to Table 5.5, surface irrigation is not recommended for soils with intake rates above what value?",
    opts: ["1.0 in/hr","0.5 in/hr","2.5 in/hr","5.0 in/hr"], a: 2,
    why: "Table 5.5 says surface methods are not recommended for intake rates over 2.5 in/hr, or for extremely low intake soils such as peats and mucks.",
    eq: null, calc: null, fig: null, table: "5.5" },
  { id: "5-135", ch: 5, sec: "5.8", page: 101, type: "table", level: 2,
    q: "According to Table 5.5, subsurface drip irrigation is best adapted to which soils?",
    opts: ["Coarse sands with high intake rates","Medium and fine-textured soils with moderate to good capillary movement","Only soils with an impervious layer below the root zone","Any soil with a slope below 2%"], a: 1,
    why: "SDI depends on capillary movement to wet the root zone, so medium and fine-textured soils suit it best. The impervious layer requirement belongs to subirrigation.",
    eq: null, calc: null, fig: null, table: "5.5" },
  { id: "5-136", ch: 5, sec: "5.8", page: 101, type: "table", level: 1,
    q: "According to Table 5.5, below-surface subirrigation is adaptable only to soils with what feature?",
    opts: ["An impervious layer below the root zone, or a high controllable water table","High intake rates above 2.5 in/hr","Slopes steeper than 10%","Coarse texture with low water holding capacity"], a: 0,
    why: "Subirrigation raises a water table under the crop, so it needs an impervious layer or a controllable high water table, and land that is level or contoured.",
    eq: null, calc: null, fig: null, table: "5.5" },
  { id: "5-137", ch: 5, sec: "5.3.2", page: 85, type: "scenario", level: 2,
    q: "A grower says: \"My pivot puts on about 1 inch, but the area under tower 3 always looks dry. How do I check it?\" What do you recommend first?",
    opts: ["Increase the depth until the dry area is green","Speed the pivot up to apply less and make it more even","Place one rain gauge near the pivot point and one at the end","Run a catch-can test with cans 5 to 15 ft apart on two radial lines and compute the distance-weighted CUH"], a: 3,
    why: "A radial catch-can test with the Heermann and Hein weighting shows the pattern and the low spot. Applying more water wastes it on the rest of the field, and two gauges cannot show the pattern.",
    eq: "5.4", calc: "eq-5.4-5.5", fig: null, table: null },
  { id: "5-138", ch: 5, sec: "5.3.4", page: 87, type: "scenario", level: 3,
    q: "A grower's catch-can test shows DU = 0.70. The root zone needs 1.0 in to refill. He asks how much must infiltrate on average so the low quarter gets the full 1.0 in. What do you tell him?",
    opts: ["1.0 in, because the average refills the root zone","0.70 in, because dz = DU × SWD","1.30 in, adding the 30% nonuniformity","About 1.43 in, because dz = dLQ / DU = 1.0 / 0.70"], a: 3,
    why: "Rearrange Eq. 5.8: dz = dLQ / DU = 1.0 / 0.70 = 1.43 in. Adding 30% (1.30 in) is close but not the same math, and 1.0 in would leave about half the field short.",
    eq: "5.8", calc: "eq-5.8", fig: null, table: null },
  { id: "5-139", ch: 5, sec: "5.3.5", page: 90, type: "scenario", level: 2,
    q: "A homeowner says: \"My lawn needs half an inch, the sprinklers put on 0.25 inch per hour, and the audit says SC = 1.4. How long do I run them?\"",
    opts: ["About 2.8 hr","2.0 hr","1.4 hr","3.5 hr"], a: 0,
    why: "Uniform run time = 0.5 / 0.25 = 2.0 hr, then × SC 1.4 = 2.8 hr so about 90% of the lawn gets enough. 2.0 hr would leave the dry spots short, and 1.4 hr divides by SC.",
    eq: "5.13", calc: "eq-5.13", fig: null, table: null },
  { id: "5-140", ch: 5, sec: "5.3.4", page: 87, type: "scenario", level: 2,
    q: "A grower ran the pivot extra hours to green up a dry ring and now his ELQ looks poor. What do you tell him?",
    opts: ["Keep adding depth until the dry ring is green, because ELQ does not matter","Extra depth on a nonuniform system mostly percolates elsewhere, so fix the uniformity problem (nozzles, pressure, leaks) instead","Switch to a faster speed so drift is smaller","Irrigate at night to remove the ring"], a: 1,
    why: "Nonuniformity on sprinklers is a hardware problem. Raising the average depth shifts the whole curve, so most of the extra water goes below the roots on the wetter parts and ELQ drops.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-141", ch: 5, sec: "5.3.6", page: 91, type: "scenario", level: 3,
    q: "A grower worried about a nitrate test well asks how much N he loses. Leachate nitrate-N is about 30 ppm, and each of 6 irrigations sends about 0.5 in below the roots. What is the season loss?",
    opts: ["About 20 lb/ac","About 3.4 lb/ac","About 90 lb/ac","About 6.8 lb/ac"], a: 0,
    why: "Per irrigation Cl = 0.226 × 30 × 0.5 = 3.39 lb/ac, and 6 irrigations give about 20 lb/ac. 3.4 is just one irrigation and 90 leaves out the 0.226 factor.",
    eq: "5.18", calc: "eq-5.18", fig: null, table: null },
  { id: "5-142", ch: 5, sec: "5.4", page: 95, type: "scenario", level: 2,
    q: "A grower reports: \"My pivot pressure is lower than usual and so is my flow rate.\" What does that point to first?",
    opts: ["Plugged sprinkler nozzles","A large leak in the pivot pipeline","A well or pump problem such as a clogged screen, declining water table, or low pump speed","The pivot set up for a higher end pressure"], a: 2,
    why: "The book says low pressure with low flow suggests a well or pump problem. A leak would usually lower pressure while flow stays up or rises, and plugged nozzles raise pressure.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-143", ch: 5, sec: "5.4", page: 95, type: "scenario", level: 2,
    q: "A drip grower says: \"My system pressure is higher than it used to be at the same setting.\" What should he check?",
    opts: ["A clogged well screen","A leak in the mainline","A declining water table","Plugged emitters or a system set up improperly, which also raises energy cost"], a: 3,
    why: "Higher than normal pressure points to plugged sprinklers or emitters or an improper setup. A leak and well problems lower pressure.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-144", ch: 5, sec: "5.4", page: 95, type: "scenario", level: 1,
    q: "A grower notices pivot pressure dropped while the flowmeter reads more than usual. What is the most likely cause?",
    opts: ["A clogged well screen","Plugged nozzles","A leak in the system","A pump running too slowly"], a: 2,
    why: "Water escaping through a leak lowers pressure and the pump delivers more flow at the lower head. Pump or well problems lower flow as well, and plugged nozzles raise pressure. Binoculars or a drone can help find leaks.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-145", ch: 5, sec: "5.6", page: 97, type: "scenario", level: 3,
    q: "A grower asks: \"My well makes 600 gpm on a 130-acre pivot with about 85% ELQ. Can it keep up with peak ET of 0.30 inch per day?\" What is the answer?",
    opts: ["Yes, it supplies about 0.40 in/d net","Yes, it supplies about 0.30 in/d net","No, it supplies about 0.21 in/d net, so stored soil water must cover the gap at peak","No, it supplies only about 0.10 in/d net"], a: 2,
    why: "600 / 130 = 4.6 gpm/ac, which is 4.6 / 18.86 = 0.245 in/d gross, and × 0.85 = 0.21 in/d net. The deficit must come from soil water during peak, so he should start the season with a full profile.",
    eq: "5.20", calc: "cn-from-flow", fig: null, table: null },
  { id: "5-146", ch: 5, sec: "5.6", page: 96, type: "scenario", level: 2,
    q: "A dealer wants to size a new pivot to meet peak daily ET with no help from soil water. The field is deep silt loam. What do you point out?",
    opts: ["Capacity must always meet peak daily ET regardless of soil","A deep high-AWC soil can supply part of peak demand, so a lower capacity designed around AD may be enough","Silt loam needs more capacity than sand","Soil water can only be used at the end of the season"], a: 1,
    why: "The peak ET method is the most conservative. Relying on stored soil water and AD can substantially reduce capacity and cost, as Figures 5.10 and 5.11 show, especially on deep high-AWC soils.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-147", ch: 5, sec: "5.6", page: 98, type: "scenario", level: 3,
    q: "A grower has the same well for two pivots, one on sand with AD = 1.0 in and one on silt loam with AD = 4.0 in. Which needs more net capacity for the same reliability, and why?",
    opts: ["The silt loam pivot, because it holds more water to refill","The sand pivot, because a small AD gives little buffer for hot spells","Both need the same, because capacity depends only on ET","Neither, because capacity depends only on rainfall"], a: 1,
    why: "Figure 5.11 shows required net capacity falls as allowable depletion rises. At 95% probability it is about 0.28 in/d at 1 in AD but about 0.20 in/d at 4 in AD.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-148", ch: 5, sec: "5.2", page: 82, type: "scenario", level: 2,
    q: "An orchard owner with plenty of money and a level block asks which system fits apples best. What does the book's reasoning support?",
    opts: ["Microirrigation, for high efficiency, minimal labor and no wetting of foliage","A traveler big gun, for versatility","Furrow with siphon tubes, for the lowest pressure","Hand move sprinklers, for the lowest equipment cost"], a: 0,
    why: "Micro systems suit high-value crops, irrigate individual plants, are easily automated and have negligible runoff. With limited funds and level land, a surface basin system is the lower cost choice.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-149", ch: 5, sec: "5.2.1", page: 79, type: "scenario", level: 2,
    q: "A golf course superintendent is choosing a system. Which type does the book describe as common on golf courses, easily automated and able to apply any depth?",
    opts: ["Big gun traveler","Side roll laterals","Furrow irrigation with gated pipe","Solid-set with underground laterals and pop-up sprinklers"], a: 3,
    why: "Solid-set systems are common on lawns, landscapes and golf courses. Each sprinkler only waters its own area, so they can be very efficient and are easily automated.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-150", ch: 5, sec: "5.3.7", page: 93, type: "scenario", level: 2,
    q: "A ditch company asks whether concrete lining is worth it on a reach through gravelly sand. Using Figure 5.8, what do you tell them?",
    opts: ["Seepage drops by only about 10%","Seepage drops from about 2.2 to 3.3 ft³/ft²/d to about 0.2 to 0.3, roughly a tenfold cut","Lining makes no difference in gravelly sand","Seepage would roughly double after lining"], a: 1,
    why: "Gravelly sand seeps about 2.2 to 3.3 ft³/ft²/d, while concrete loses about 0.2 to 0.3. Lining cuts seepage by about ten times, though whether that water is truly saved depends on who uses the seepage downstream.",
    eq: null, calc: "ditch-seepage", fig: "5.8", table: null },
  { id: "5-151", ch: 5, sec: "5.6", page: 99, type: "scenario", level: 2,
    q: "A field needs 700 gpm gross at the field, but it is fed through an earthen lateral with about 80% conveyance efficiency. How much should the grower order at the headgate?",
    opts: ["About 875 gpm","About 560 gpm","About 840 gpm","700 gpm"], a: 0,
    why: "Qf = 700 / 0.80 = 875 gpm. 560 gpm multiplies by 0.80, and 840 gpm adds 20% instead of dividing by 0.80.",
    eq: "5.21", calc: "eq-5.21", fig: null, table: null },
  { id: "5-152", ch: 5, sec: "5.7", page: 100, type: "scenario", level: 2,
    q: "A furrow irrigator always runs 12-hour sets. In June the soil water deficit is only about 1 in. What do you suggest?",
    opts: ["Shorten the set or reduce the flow per furrow so infiltration matches the smaller deficit","Keep 12-hour sets, because the soil will store the extra","Lengthen to 24-hour sets to save labor","Irrigate every day with 12-hour sets"], a: 0,
    why: "A fixed 12-h set applies roughly the same depth whatever the SWD, so early season water goes to deep percolation. Adjust set time or flow so the effective depth fits the SWD.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-153", ch: 5, sec: "5.7", page: 100, type: "scenario", level: 1,
    q: "A district grower says: \"I get water 4 days, then go 10 days without.\" What are the duration and rotation?",
    opts: ["Duration 14 d and rotation 4 d","Duration 10 d and rotation 14 d","Duration 4 d and rotation 10 d","Duration 4 d and rotation 14 d"], a: 3,
    why: "Duration is how long water is provided, 4 d. Rotation is the time between successive starts, 4 + 10 = 14 d.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-154", ch: 5, sec: "5.10", page: 101, type: "scenario", level: 3,
    q: "A water board member says: \"If every grower in our groundwater basin converts from furrow to pivots, the aquifer decline will stop.\" What is the best response?",
    opts: ["Not necessarily, because much furrow deep percolation was recharging the aquifer, and only reduced ET (consumptive use) cuts net depletion","Yes, because pivots apply less water, the aquifer will recover","Yes, because higher application efficiency always saves water","No, because pivots use more water than furrows"], a: 0,
    why: "Pumping drops, which saves energy and helps water quality, but the reduced deep percolation was recharge. Unless ET falls (for example if the saved water irrigates more acres, ET rises), net depletion may not change.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-155", ch: 5, sec: "5.10", page: 101, type: "scenario", level: 3,
    q: "An upstream canal company plans to line its ditches. A downstream irrigator worries about his supply. Why might he be right?",
    opts: ["Lining increases evaporation from the canal","Downstream users often depend on upstream seepage and return flows","Lining raises the water table downstream","Lining reduces the upstream diversion right"], a: 1,
    why: "The book notes that downstream irrigators often depend on the losses of upstream irrigators. Water saved by lining may simply be water that used to reach the downstream user.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-156", ch: 5, sec: "5.9", page: 101, type: "scenario", level: 1,
    q: "A new hire will move a high-clearance sprayer near a pivot and overhead power lines. What safety point from the book matters most?",
    opts: ["Only the pump panel carries voltage","Pivot towers are grounded, so there is no electrical risk","Be cautious near overhead lines and remember systems run on high voltage (480 V), so a metal structure in a wet field can electrocute","Electrical risk matters only during lightning"], a: 2,
    why: "The book stresses electrical safety: high voltage, metal structures and wet conditions create electrocution risk, and managers must be cautious near overhead power lines.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-157", ch: 5, sec: "5.3.2", page: 86, type: "scenario", level: 3,
    q: "A turf manager's catch-can audit on a sports field shows DU = 0.55. He plans to just add run time. What do you advise?",
    opts: ["DU 0.55 is excellent for turf","Adding run time is the best fix because DU cannot be changed","DU is well below the 0.7 guideline, so fix spacing, pressure and heads first, because more run time will waste water","Cut run time in half to save water"], a: 2,
    why: "With DU 0.55 the SC is 1.8, so run times would grow by 80% to cover the dry spots. Repairs that raise DU save more water than stretching run times.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-158", ch: 5, sec: "5.3.3", page: 86, type: "scenario", level: 3,
    q: "A grower wants 95% of his field adequately irrigated instead of 90%. What is the tradeoff?",
    opts: ["He can do it by lowering the average depth","Nothing changes because adequacy is set by the system","Deep percolation decreases because more of the field is wet","He must raise the average depth, which increases deep percolation and lowers application efficiency"], a: 3,
    why: "With fixed uniformity, more adequacy means a higher average application, so more of the field gets more than the SWD. That is the direct link between Ea and uniformity the book describes.",
    eq: null, calc: null, fig: null, table: null },
  { id: "5-159", ch: 5, sec: "5.3.4", page: 89, type: "scenario", level: 2,
    q: "A furrow grower with a tailwater pit that pumps back onto the same field asks what depth to use as da in ELQ. What do you tell him?",
    opts: ["The volume pumped from the well (original source) divided by the area, not counting reused tailwater","The gross depth including the reused tailwater","The depth of runoff collected in the pit","The average depth infiltrated"], a: 0,
    why: "da is always the water taken from the original source divided by the area. For a closed reuse system da = dg(1 − Rr Rt), which is less than the gross depth delivered to the furrows.",
    eq: "5.12a", calc: "eq-5.12", fig: null, table: null },
  { id: "5-160", ch: 5, sec: "5.3.1", page: 82, type: "scenario", level: 1,
    q: "A grower says: \"On windy days I lose half my pivot water to evaporation.\" What is the better explanation?",
    opts: ["Droplet evaporation is usually under 10%, and wind losses are mostly drift, which is often larger than evaporation","Evaporation from droplets really is about 50% on windy days","Wind has no effect on losses","Losses on windy days are mostly deep percolation"], a: 0,
    why: "Research shows little evaporation of drops in the air, usually well under 10% of applied water. Wind blows drops off target as drift and also hurts uniformity.",
    eq: null, calc: null, fig: null, table: null }
]);
